mapper.select:
SELECT company_id AS companyId, company_code AS companyCode, company_name AS companyName, company_type_code AS companyTypeCode FROM tb_product_company WHERE is_active = true
AND company_type_code = #{insuranceTypeCode}
ORDER BY company_name

SELECT p.product_id AS productId, p.company_id AS companyId, p.product_name AS productName, p.product_status_code AS productStatusCode, p.sales_channel AS salesChannel, p.sale_start_date AS saleStartDate FROM tb_product_master p JOIN tb_product_company c ON p.company_id = c.company_id WHERE p.is_active = true
AND c.company_code = #{companyCode}
ORDER BY p.product_name

SELECT m.material_id AS materialId, p.product_id AS productId, p.product_name AS productName, c.company_name AS companyName, m.material_title AS materialTitle, t.type_name AS materialTypeName, v.file_path AS fileUrl, v.file_extension AS fileExtension, CASE WHEN t.type_code = 'SUMMARY' THEN 'fa-file-lines' WHEN t.type_code = 'TERMS' THEN 'fa-book' WHEN t.type_code = 'METHODS' THEN 'fa-briefcase' WHEN t.type_code = 'BROCHURE' THEN 'fa-image' WHEN t.type_code = 'NEEDS' THEN 'fa-lightbulb' ELSE 'fa-file' END AS iconClass FROM tb_product_material_version v JOIN tb_product_material m ON v.material_id = m.material_id JOIN tb_product_master p ON m.product_id = p.product_id JOIN tb_product_company c ON p.company_id = c.company_id JOIN tb_product_material_type t ON m.material_type_id = t.material_type_id WHERE v.is_current = true AND m.is_active = true AND p.is_active = true
AND c.company_code = #{companyCode}
AND c.company_type_code = #{insuranceTypeCode}
AND p.product_id = #{productId}
AND t.type_code = #{materialTypeCode}
ORDER BY m.created_at DESC
